let TOPICS=[{"id":1,"field":"임신·출산","topic":"아이를 갖고자 할 때","desc":"임신 준비 및 임신 했을 때 필요한 정보와 서비스를 확인할 수 있습니다.","icon":"🤱","color":"#e8f4fd"},{"id":2,"field":"임신·출산","topic":"임신에 어려움을 겪을 때","desc":"부부가 임신을 위해 노력했음에도 일정기간 임신이 되지 않는 상태에서 필요한 사항을 안내합니다.","icon":"💊","color":"#e8f4fd"},{"id":3,"field":"임신·출산","topic":"아이가 태어났을 때","desc":"출산으로 신생아가 세상에 태어난 상황으로, 출생신고 등 법적 절차가 요구됩니다.","icon":"👶","color":"#e8f4fd"},{"id":4,"field":"육아","topic":"아이를 양육할 때","desc":"부모 또는 보호자가 아이의 발달·건강·교육 등을 돌보려고 할 때 필요한 사항을 안내합니다.","icon":"🧒","color":"#fff8e1"},{"id":5,"field":"육아","topic":"육아휴직을 하려고 할 때","desc":"근로자가 자녀 양육을 위해 일정 기간 휴직을 신청·사용할 때 필요한 사항을 안내합니다.","icon":"🏠","color":"#fff8e1"},{"id":6,"field":"육아","topic":"아이를 어린이집에 보내려고 할 때","desc":"보육시설에 자녀를 위탁하여 양육 및 교육을 받기 위해 필요한 사항을 안내합니다. (0~5세)","icon":"🏫","color":"#fff8e1"},{"id":7,"field":"결혼","topic":"누군가와 결혼할 때","desc":"법적으로 혼인신고를 하고 부부 관계를 성립하는 상황에서 필요한 사항을 안내합니다.","icon":"💍","color":"#fce4ec"},{"id":8,"field":"결혼","topic":"외국인과 결혼할 때","desc":"대한민국 국민과 외국인 간의 혼인 관계 성립 시 혼인신고 및 체류 자격 관련 절차를 안내합니다.","icon":"🌏","color":"#fce4ec"},{"id":9,"field":"이사","topic":"이사를 할 때","desc":"거주지를 다른 장소로 이전하는 것으로, 전입신고 등 행정절차가 수반된 사항을 안내합니다.","icon":"📦","color":"#e8f5e9"},{"id":10,"field":"이사","topic":"셀프등기를 하려고 할 때","desc":"부동산 소유권 변동 시 법무사 대리 없이 개인이 직접 등기를 신청할 때 필요한 사항을 안내합니다.","icon":"🏡","color":"#e8f5e9"},{"id":11,"field":"사망","topic":"누군가가 돌아가셨을 때","desc":"가족 또는 지인이 사망한 상황으로, 장례 절차와 사망신고, 상속 관련 법적 절차를 안내합니다.","icon":"🕊️","color":"#f3e5f5"},{"id":12,"field":"사망","topic":"상속을 할 때","desc":"사망자의 재산과 권리, 의무가 법률상 상속인에게 이전되는 절차 및 필요 사항을 안내합니다.","icon":"📜","color":"#f3e5f5"},{"id":13,"field":"보건·복지","topic":"치매가 의심될 때","desc":"인지 기능이 점차 저하되어 일상생활에 어려움을 겪게 되었을 때 필요한 사항을 안내합니다.","icon":"🧠","color":"#e0f7fa"},{"id":14,"field":"보건·복지","topic":"암 진단을 받았을 때","desc":"의료기관에서 조직검사 등으로 암세포가 확인된 상태에서 필요한 사항을 안내합니다.","icon":"🏥","color":"#e0f7fa"},{"id":15,"field":"보건·복지","topic":"돌봄이 필요할 때(노인)","desc":"65세 이상 노인이 일상생활 수행이 어려워 장기요양 서비스가 필요한 상황을 안내합니다.","icon":"👴","color":"#e0f7fa"}];

let STEPS={"1":[{"nr":1,"task":"임신 준비 하기","desc":"임신을 준비하기 위한 정보와 서비스를 확인하세요."},{"nr":2,"task":"임신 확인 하기","desc":"혈액검사, 초음파 등 산부인과 병의원에서 임신 사실을 확인하세요."},{"nr":3,"task":"임산부 등록하기","desc":"등록된 주소지의 보건소 방문 또는 e보건소 사이트 및 아이마중 앱을 통해 임산부 등록하세요."},{"nr":4,"task":"임신 관련 지원금 신청 하기","desc":"임신 관련 지원금을 확인하고 신청하세요."},{"nr":5,"task":"임신 중 잘 지내기","desc":"임신 중 건강관리, 예방접종 등 필요한 검사를 받고, 마음의 안정을 취하세요."},{"nr":6,"task":"출산 준비 하기","desc":"산후조리원 예약, 아기용품 구매 등 출산을 위해 준비하세요."}],"2":[{"nr":1,"task":"난임에 대해 이해하기","desc":"난임 정의, 난임 부부의 심리적 어려움, 난임의 원인, 난임 검사, 난임 치료에 대한 정보를 확인하세요."},{"nr":2,"task":"난임 검사","desc":"난임 여부를 확인하기 위한 검사 및 진단을 받으세요. 또한 난임진단 검사비 지원을 받는 대상자인지 확인하세요."},{"nr":3,"task":"난임 시술 및 혜택 받기","desc":"난임 치료를 위한 시술과 비용 지원, 휴가 등 치료 과정의 실질적 지원을 받으세요."},{"nr":4,"task":"심리적 지원 및 스트레스 관리","desc":"난임 과정 중 겪을 수 있는 정서적 고통을 완화하고, 심리 상담을 받으세요."}],"3":[{"nr":1,"task":"출생 확인 하기","desc":"자가, 병원 의원, 조산원 등 출생장소에서 아기의 출생을 확인하세요."},{"nr":2,"task":"산후관리 하기","desc":"임신과 출산으로 인해 변화된 산모의 몸이 임신 전 상태로 회복되도록 관리하세요."},{"nr":3,"task":"출생신고 하기","desc":"출생 후 1개월 이내에 주민등록상 주소지 관할 시, 읍, 면, 동 주민센터에서 아기의 출생을 신고 하세요."},{"nr":4,"task":"출산 지원 신청 하기","desc":"출산 후 받을 수 있는 첫만남이용권, 아동수당 등 다양한 수혜서비스를 확인하고 신청하세요."},{"nr":5,"task":"출산휴가 및 육아휴직 신청 하기","desc":"출산 전후 및 육아휴직을 위해 회사에 관련 규정을 확인하고 출산예정일 등을 고려하여 회사에 휴가 및 휴직을 신청하세요."},{"nr":6,"task":"영유아 검진 예약 하기","desc":"생후 14일부터 71개월까지의 영유아를 대상으로 하는 검진이며, 8차로 검진 시기가 구성되어 있어 시기별 의료기관에 영유아 검진을 예약하세요."},{"nr":7,"task":"어린이집 입소대기 신청 하기","desc":"부모 또는 보호자는 자녀를 어린이집에 입소하기 위해 미리 대기신청을 하세요."},{"nr":8,"task":"그 밖에 할 일","desc":"결핵 예방접종, 아기 통장 개설하기 등 그밖에 도움이 될만한 사항을 확인하세요."}],"4":[{"nr":1,"task":"양육정보 수집하기","desc":"출산 전후 부모가 육아와 발달, 안전, 영양, 서비스 활용 정보를 확인하세요."},{"nr":2,"task":"가정방문 신청하기","desc":"부모와 아이의 건강관리 교육 및 심리사회적 지원 등을 통한 건강수준 향상 및 양육역량 강화를 위하여 가정방문을 신청하세요."},{"nr":3,"task":"건강검진 및 예방접종 하기","desc":"신생아 및 영유아 건강을 관리하세요."},{"nr":4,"task":"돌봄 공백 해결하기","desc":"부모 부재 시 지원받을 수 있는 방법을 확인하세요"},{"nr":5,"task":"재정 지원 활용 하기","desc":"국가·지자체 양육수당, 장려금 등 활용하세요."}],"5":[{"nr":1,"task":"육아휴직 이해하기","desc":"육아 휴직에 대해 파악하여 내가 사용할 수 있는지와 어떻게 사용하는지를 결정하세요."},{"nr":2,"task":"육아휴직 신청 및 확인서 발급 하기","desc":"회사에 공식적으로 휴직을 요청해 승인을 받고, 육아휴직확인서를 발급 받으세요."},{"nr":3,"task":"육아휴직 급여 신청 하기","desc":"근로자가 고용센터 혹은 온라인(고용24)에서 급여를 청구하세요."},{"nr":4,"task":"지자체 장려금 확인 및 신청 하기","desc":"지자체 아빠 육아휴직 장려금을 확인하시고 신청하세요."},{"nr":5,"task":"휴직기간동안 4대보험료 처리 하기","desc":"육아휴직 기간 동안 4대 보험은 종류에 따라 납부 유예, 납부 예외, 부과 제외 등으로 다르게 처리됩니다. 근로자가 직접 신고할 수도 있지만, 대개 회사의 인사·경리 부서를 통해 처리됩니다."}],"6":[{"nr":1,"task":"아동등록 하기","desc":"어린이집에 입소할 자녀를 등록하세요."},{"nr":2,"task":"어린이집 검색하기","desc":"어린이집을 검색하고 신청할 어린이집을 선택하세요."},{"nr":3,"task":"입소대기 신청 하기","desc":"어린이집 대기 예약 신청을 하세요."},{"nr":4,"task":"증빙 자료 제출 하기","desc":"어린이집에서 자동 연계되는 자격을 제외하고 입소관련 서류 일체를 제출하세요."},{"nr":5,"task":"보육료 결제 하기","desc":"어린이집을 이용하는 영유아의 보호자는 정부에서 지원하는 보육료를 정해진 방법으로 결제·지급하세요."},{"nr":6,"task":"특수 어린이집 서비스 찾기","desc":"연장보육반, 장애통합어린이집 등 특수 상황의 어린이집 서비스를 찾아보세요."}],"7":[{"nr":1,"task":"결혼식 준비하기","desc":"스튜디오, 드레스, 웨딩홀 업체 선정 등 결혼식을 준비하세요."},{"nr":2,"task":"신혼집 마련하기","desc":"기준 설정, 인프라, 이사 등을 고려하여 자금 계획에 따라 신혼집을 마련하세요."},{"nr":3,"task":"혼인신고 하기","desc":"필요 구비 서류 등을 준비하여 법적으로 부부 관계를 성립하기 위한 혼인신고를 하세요."},{"nr":4,"task":"결혼 관련 지원 받기","desc":"다양한 제도에 따른 결혼 관련 지원을 받으세요."}],"8":[{"nr":1,"task":"요건 및 절차 이해하기","desc":"외국인(한국비자가 없는 외국인)과 혼인을 하기 위한 절차 및 요건을 확인하세요."},{"nr":2,"task":"국제결혼안내프로그램 신청/이수 하기","desc":"국제결혼 관련 법령 및 현지 국가의 문화·관습 등을 소개하여 국제결혼에 대한 이해도를 높이고 행복한 가정을 형성·유지할 수 있도록 안내프로그램을 이수하세요."},{"nr":3,"task":"해외 혼인신고 하기","desc":"혼인신고를 위해 결혼사실 없음 확인을 위한 서류를 발급 및 공증 받은 서류를 해당 국가 관서에 제출하여 혼인신고를 하세요."},{"nr":4,"task":"국내 혼인신고 하기","desc":"해당 국가 관서에서 발급받은 혼인증명서를 한국어로 번역 및 공증하여 국내 혼인시고를 하세요."},{"nr":5,"task":"결혼이민비자(F6) 신청 하기","desc":"한국에서 혼인이 유효하게 성립되어 있고, 우리 국민과 결혼생활을 지속하기 위해 결혼이민비자를 신청하세요."},{"nr":6,"task":"조기적응프로그램 이수 하기","desc":"외국인은 우리 사회에 빨리 적응하는데 필요한 생활정보, 기초법 습득 기회를 제공하는 프로그램을 이수하세요."},{"nr":7,"task":"외국인 등록 및 체류기간 연장 신청 하기","desc":"체류기간연장 및 외국인등록증을 발급받으세요."},{"nr":8,"task":"한국생활 정착 준비 하기","desc":"건강보험 가입, 은행 계좌 개설 등 생활에 필요한 사항을 준비하세요."},{"nr":9,"task":"영주자격(F5) 획득 혹은 대한민국 국적 귀화 하기","desc":"영주자격을 획득하거나 대한민국 국적으로 귀화를 준비하세요."},{"nr":10,"task":"혜택 확인하기","desc":"한국어 교육, 자녀 양육지원, 주거 지원, 생활안정자금 등 혜택을 확인하세요."}],"9":[{"nr":1,"task":"이사 업체 선정 하기","desc":"여러 업체에서 견적을 받아 비교하고, 계약서 작성 시 인원, 비용, 추가 서비스 등을 확인하세요."},{"nr":2,"task":"불필요한 물품 처리 하기","desc":"폐가구, 폐전자제품은 주민센터 스티커, 인터넷 신고, 무료수거 서비스 등을 활용해 미리 처리하세요."},{"nr":3,"task":"주소 이전 및 우편물 관리 하기","desc":"우체국 주소 이전 서비스를 신청해 우편물이 새 주소로 전달되도록 하고, 통장·신용카드·전화 등 주소 변경도 미리 해두세요."},{"nr":4,"task":"공과금 및 관리비 정산 하기","desc":"이사 전날 혹은 당일 이사 전 주거지의 전기, 가스, 수도, 아파트 관리비 등 정산하세요."},{"nr":5,"task":"전입신고 및 확정일자 받기","desc":"새로운 주거지로 이사한 후 주민센터에 방문하거나 온라인으로 새로운 주소지를 등록하고, 해당 임대차계약서에 확정일자를 받으세요."},{"nr":6,"task":"가스, 전기, 수도 등 명의변경 하기","desc":"새로운 주거지의 가스, 전기, 수도 등 각 서비스 공급기관에 명의 변경을 신청하세요."},{"nr":7,"task":"자녀 전학 수속 하기","desc":"이사로 인해 자녀의 전학이 필요한 경우 전학 수속을 진행하세요."}],"10":[{"nr":1,"task":"거래대상 물건 확인하기","desc":"등기사항전부증명서 등 관련 서류를 발급하여 소유자 및 권리관계를 확인하고, 구조, 면적 등을 확인하세요."},{"nr":2,"task":"부동산 거래계약 하기","desc":"계약 시 유의사항, 매매계약서 작성에 필요한 준비서류 등을 확인하세요."},{"nr":3,"task":"부동산 거래신고 하기","desc":"부동산 또는 부동산을 취득할 수 있는 권리에 대한 매매계약을 체결한 때 실제거래가격 등을 시·군·구청에 신고하는 방법과 유의사항을 확인하세요."},{"nr":4,"task":"거래계약 이행 하기","desc":"중도금, 잔금 등 대금 지급시 유의사항을 확인하세요."},{"nr":5,"task":"취득세 신고하기","desc":"취득세를 신고하고 납부 확인하세요."},{"nr":6,"task":"토지대장, 건축물대장 발급 받기","desc":"토지대장 및 건축물 대장을 발급 받으세요."},{"nr":7,"task":"인지세, 주택채권, 등기신청 수수료 납부 하기","desc":"국민주택채권, 전자수입인지 매입 및 등기신청수수료를 은행에 납부하세요."},{"nr":8,"task":"소유권이전 등기신청 하기","desc":"등기신청서 작성 및 구비서류를 편철하여 관할 등기소에 방문 제출하세요."}],"11":[{"nr":1,"task":"사망 확인받기","desc":"병원 또는 의사에게 요청하여 사망진단서를 발급받으세요. ※ 자택이나 요양시설에서 사망한 경우, 112에 연락하여 경찰의 확인 후 의사의 사망진단서 또는 사체 검안서를 발급받아야 합니다."},{"nr":2,"task":"장례 준비하기","desc":"장례식장 선정 및 예약, 시신 이송과 고인 안치, 부고 및 조문 안내, 장례 용품 및 영정사진 준비, 입관 및 장례의식, 발인 및 장지결정을 하세요."},{"nr":3,"task":"장사시설 이용하기","desc":"화장, 봉안시설, 수목원 자연장지 등 장사시설을 이용하세요."},{"nr":4,"task":"사망신고 하기","desc":"사망자의 마지막 주소지를 관할하는 동주민센터나 가까운 전국 구청(읍면사무소 가능)에서 신고하세요."},{"nr":5,"task":"장례 후 행정처리 하기","desc":"자동차 이전 등록, 유족연금 신청, 고인 명의의 계약을 해지하세요."},{"nr":6,"task":"사망 관련 급여·보상 신청하기","desc":"장례소요비용 등 사망관련 급여 및 보상금을 신청하세요."}],"12":[{"nr":1,"task":"사망신고와 상속 개시","desc":"사망신고를 통해 공식적인 상속 절차를 개시하세요."},{"nr":2,"task":"재산 및 채무 내역 확인하기","desc":"안심상속 원스톱 서비스 등으로 금융재산, 부동산, 채무 등을 파악하세요."},{"nr":3,"task":"상속의 승인 혹은 포기 결정하기","desc":"상속인이 상속재산을 조사한 뒤 상속으로 인하여 물려받을 재산과 채무를 비교하여 상속의 승인·포기 등을 결정하세요."},{"nr":4,"task":"상속재산 분리청구 및 유류분 반환청구 하기","desc":"상속받은 재산을 분리하여 청구하고, 유류분을 반환받기 위한 절차를 진행하세요."},{"nr":5,"task":"상속재산 분할 합의하기","desc":"공동상속인들이 피상속인(사망자)의 재산을 어떻게 나눌지 합의하세요."},{"nr":6,"task":"상속등기와 상속관련 세금납부 하기","desc":"상속등기 신청, 상속재산 이전 및 상속관련 세금 신고와 세금을 납부 하세요."}],"13":[{"nr":1,"task":"치매에 대해 이해하기","desc":"치매는 단계별로 증상이 다르게 나타나며, 각 단계마다 필요한 지원과 관리도 달라지기 때문에 적절한 대응을 준비하기 위하여 자신의 상태를 잘 이해하세요."},{"nr":2,"task":"치매 환자로 등록하기","desc":"치매안심센터나 보건소를 방문하여 필요서류를 제출하여 치매 환자로 등록하고, 장기요양 등급 신청 등 치매 관련 사항을 등록해 주세요."},{"nr":3,"task":"치매 치료 지원 받기","desc":"치매 치료와 관련된 정기적 및 비정기적으로 소요되는 비용을 지원 받으세요."},{"nr":4,"task":"치매 돌봄 서비스 마련하기","desc":"방문요양, 단기보호, 노인맞춤돌봄 서비스 등 가정 내 상황에 맞게 치매 돌봄 서비스를 마련하세요."}],"14":[{"nr":1,"task":"암에 대해 이해하기","desc":"암은 진행에 따라 초기에서 말기로 구분되며, 원인·진행·치료 방법을 이해하여 상황에 맞는 적절한 계획을 세우세요."},{"nr":2,"task":"암 환자로 등록하기","desc":"병원에서 암 진단을 받은 뒤 담당 의사의 확인 및 진단서를 받은 후, 가까운 국민건강보험공단 지사나 병원에서 산정특례 등록 신청서를 제출하여 등록하세요."},{"nr":3,"task":"암 관련 지원 받기","desc":"암 진단·치료비, 약제비 등 암 치료 및 관리에 필요한 암 관련 지원을 받으세요."},{"nr":4,"task":"암 치료 및 관리 하기","desc":"암 치료 과정에서는 오심, 구토, 탈모, 감염 등 부작용이 발생할 수 있으므로, 의료진과 상의하여 증상을 관리하고 영양·생활습관을 조절해서 안전하게 치료를 받으세요."},{"nr":5,"task":"정기 검진 받기","desc":"치료 후에는 암 재발이나 전이 여부, 부작용 관리 등을 위해 정기적으로 진료와 검사를 받으세요."}],"15":[{"nr":1,"task":"장기요양 인정 신청 하기","desc":"본인 또는 대리인이 국민건강보험공단 각 지사에서 장기요양 인정을 신청하세요."},{"nr":2,"task":"공단 방문조사 받기","desc":"공단 직원이 신청자의 가정을 방문 하면, 신체 및 정신 상태와 일상 생활 가능 정도 조사에 응하세요."},{"nr":3,"task":"장기요양 등급 판정 받기","desc":"장기요양 등급판정위원회에서 신청자의 상태와 의사소견서를 종합적으로 평가한 등급 판정을 받으세요."},{"nr":4,"task":"장기요양서비스 이용 하기","desc":"수급자가 이용 가능한 장기요양기관 정보, 복지용구 급여 확인서 등을 받아 필요한 서비스 선택 후 해당 기관과 계약을 체결 하여 서비스를 이용하세요."},{"nr":5,"task":"그 밖에 노인 돌봄 관련 지원 받기","desc":"노인장기요양보험 서비스 외에 노인 돌봄 관련 지원을 받으세요."}]};

